const u = $input.first().json;

const baseUrl = String(u.smartStorageUrl || '').trim().replace(/\/+$/, '');
if (!baseUrl || baseUrl.includes('PI-IP')) {
  throw new Error('Im Knoten ⚙️ KONFIGURATION zuerst smartStorageUrl setzen, z. B. http://192.168.178.120:8090');
}

let chatId = null;
let text = '';
let isCallback = false;

if (u.callback_query) {
  isCallback = true;
  chatId = u.callback_query.message?.chat?.id;
  text = String(u.callback_query.data || '').trim();
} else if (u.message) {
  chatId = u.message.chat?.id;
  text = String(u.message.text || '').trim();
}

if (chatId === null || chatId === undefined) return [];

const allowed = String(u.allowedChatIds || '')
  .split(',')
  .map(v => v.trim())
  .filter(Boolean);
if (allowed.length && !allowed.includes(String(chatId))) return [];

let action = 'help';
let query = '';
let quantity = 1;

if (!text) {
  action = 'help';
} else if (isCallback && text.includes(':')) {
  const pos = text.indexOf(':');
  action = text.slice(0, pos).trim().toLowerCase();
  query = text.slice(pos + 1).trim();
} else if (!text.startsWith('/')) {
  action = 'stock';
  query = text;
} else {
  const firstSpace = text.indexOf(' ');
  const rawCommand = (firstSpace === -1 ? text : text.slice(0, firstSpace))
    .toLowerCase()
    .replace(/@.*$/, '');
  const rest = firstSpace === -1 ? '' : text.slice(firstSpace + 1).trim();

  const commands = {
    '/start': 'help',
    '/hilfe': 'help',
    '/help': 'help',
    '/bestand': 'stock',
    '/stock': 'stock',
    '/plus': 'add',
    '/add': 'add',
    '/einlagern': 'add',
    '/minus': 'remove',
    '/remove': 'remove',
    '/entnehmen': 'remove',
    '/licht': 'locate',
    '/leuchten': 'locate',
    '/locate': 'locate',
    '/suche': 'search',
    '/search': 'search',
    '/faecher': 'assignments',
    '/fächer': 'assignments',
    '/drawers': 'assignments',
    '/events': 'events',
    '/verlauf': 'events',
    '/history': 'events',
    '/aus': 'off',
    '/off': 'off'
  };

  action = commands[rawCommand] || 'help';
  query = rest;

  if ((action === 'add' || action === 'remove') && rest) {
    const parts = rest.split(/\s+/);
    if (parts.length >= 2 && /^\d+$/.test(parts[parts.length - 1])) {
      quantity = Math.max(1, Math.min(9999, Number(parts.pop())));
      query = parts.join(' ').trim();
    }
  }
}

return [{
  json: {
    chatId: String(chatId),
    requestUrl: `${baseUrl}/api/telegram/action`,
    requestBody: { action, query, quantity },
    inputText: text
  }
}];
